package dev.rag.identity;

import dev.rag.common.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import java.util.*;

@Service
public class IdentityService {
 private final Db db;private final AccessPolicy access;private final TransactionTemplate tx;
 public IdentityService(Db db,AccessPolicy access,TransactionTemplate tx){this.db=db;this.access=access;this.tx=tx;}
 public void audit(Actor a,String action,String type,String id){db.insert("audit_event",Db.params("tenant_id",a.tenantId(),"id",Json.id(),"actor_id",a.userId(),"action",action,"object_type",type,"object_id",id,"outcome","SUCCESS","metadata_json","{}"));}
 public void epoch(Actor a){db.exec("UPDATE tenant SET security_epoch=security_epoch+1 WHERE id=:t",Map.of("t",a.tenantId()));}
 public List<Map<String,Object>> users(Actor a){access.requireAdmin(a);return db.list("SELECT id,login_name AS loginName,is_admin AS admin,status FROM app_user WHERE tenant_id=:t",Map.of("t",a.tenantId()));}
 public List<Map<String,Object>> groups(Actor a){access.requireAdmin(a);return db.list("SELECT id,name FROM user_group WHERE tenant_id=:t",Map.of("t",a.tenantId()));}
 public Map<String,Object> me(Actor a){var r=db.one("SELECT login_name AS loginName FROM app_user WHERE tenant_id=:t AND id=:u",Db.params("t",a.tenantId(),"u",a.userId()));r.putAll(Db.params("userId",a.userId(),"tenantId",a.tenantId(),"admin",a.admin(),"groups",db.list("SELECT g.id,g.name FROM user_group g JOIN group_member m ON m.tenant_id=g.tenant_id AND m.group_id=g.id WHERE m.tenant_id=:t AND m.user_id=:u",Db.params("t",a.tenantId(),"u",a.userId()))));return r;}
 public List<Map<String,Object>> knowledgeBases(Actor a){return db.list("SELECT kb.id,kb.name,kb.row_version AS rowVersion FROM knowledge_base kb WHERE kb.tenant_id=:t AND kb.status='LIVE' AND EXISTS (SELECT 1 FROM kb_grant kg WHERE kg.tenant_id=kb.tenant_id AND kg.kb_id=kb.id AND "+AccessPolicy.principal("kg")+")",Db.params("t",a.tenantId(),"u",a.userId()));}
 public Map<String,Object> createKb(Actor a,Map<String,Object> body){access.requireAdmin(a);String name=required(body,"name",255);return access.write(a,()->tx.execute(s->{String id=Json.id();db.insert("knowledge_base",Db.params("tenant_id",a.tenantId(),"id",id,"name",name));replaceGrants(a,"kb_grant","kb_id",id,readers(body));epoch(a);audit(a,"KB_CREATE","KB",id);return Map.of("id",id,"name",name,"rowVersion",0);}));}
 public Map<String,Object> acl(Actor a,String id,boolean document){access.requireAdmin(a);String table=document?"document":"knowledge_base",grants=document?"document_grant":"kb_grant",fk=document?"document_id":"kb_id";var r=db.one("SELECT id,row_version AS rowVersion"+(document?",acl_mode AS mode":"")+" FROM "+table+" WHERE tenant_id=:t AND id=:id",Db.params("t",a.tenantId(),"id",id));r.put("readers",db.list("SELECT principal_type AS type,user_id AS userId,group_id AS groupId FROM "+grants+" WHERE tenant_id=:t AND "+fk+"=:id",Db.params("t",a.tenantId(),"id",id)));return r;}
 public Map<String,Object> setAcl(Actor a,String id,boolean document,Map<String,Object> body){access.requireAdmin(a);long expected=number(body,"expectedVersion");String table=document?"document":"knowledge_base", mode=Json.str(body,"mode");if(document&&!Set.of("INHERIT","RESTRICT").contains(mode))throw invalid("mode 无效");return access.write(a,()->tx.execute(s->{var p=Db.params("t",a.tenantId(),"id",id,"v",expected,"mode",mode);int n=db.exec("UPDATE "+table+" SET row_version=row_version+1"+(document?",acl_mode=:mode":"")+" WHERE tenant_id=:t AND id=:id AND row_version=:v",p);if(n!=1)throw conflict();replaceGrants(a,document?"document_grant":"kb_grant",document?"document_id":"kb_id",id,readers(body));epoch(a);audit(a,"ACL_UPDATE",document?"DOCUMENT":"KB",id);return acl(a,id,document);}));}
 public Map<String,Object> members(Actor a,String group,Map<String,Object> body){access.requireAdmin(a);return access.write(a,()->tx.execute(s->{db.one("SELECT id FROM user_group WHERE tenant_id=:t AND id=:id",Db.params("t",a.tenantId(),"id",group));if(db.exec("UPDATE tenant SET security_epoch=security_epoch+1 WHERE id=:t AND security_epoch=:v",Db.params("t",a.tenantId(),"v",number(body,"expectedSecurityEpoch")))!=1)throw conflict();Object raw=body.get("userIds");if(!(raw instanceof List<?> ids)||ids.size()>1000)throw invalid("userIds 无效");db.exec("DELETE FROM group_member WHERE tenant_id=:t AND group_id=:g",Db.params("t",a.tenantId(),"g",group));for(Object id:new LinkedHashSet<>(ids)){db.one("SELECT id FROM app_user WHERE tenant_id=:t AND id=:id",Db.params("t",a.tenantId(),"id",id));db.insert("group_member",Db.params("tenant_id",a.tenantId(),"id",Json.id(),"group_id",group,"user_id",id));}audit(a,"GROUP_MEMBERS_UPDATE","GROUP",group);return Map.of("id",group,"updated",true);}));}
 public void replaceGrants(Actor a,String table,String fk,String id,List<Map<String,Object>> readers){db.exec("DELETE FROM "+table+" WHERE tenant_id=:t AND "+fk+"=:id",Db.params("t",a.tenantId(),"id",id));Set<String> seen=new HashSet<>();for(var r:readers){String type=Json.str(r,"type").toUpperCase(Locale.ROOT),user=Json.str(r,"userId"),group=Json.str(r,"groupId");if(!Set.of("USER","GROUP","ALL").contains(type)||type.equals("ALL")&&table.equals("document_grant"))throw invalid("授权主体无效");if(type.equals("USER"))db.one("SELECT id FROM app_user WHERE tenant_id=:t AND id=:id",Db.params("t",a.tenantId(),"id",user));if(type.equals("GROUP"))db.one("SELECT id FROM user_group WHERE tenant_id=:t AND id=:id",Db.params("t",a.tenantId(),"id",group));if(!seen.add(type+user+group))continue;db.insert(table,Db.params("tenant_id",a.tenantId(),"id",Json.id(),fk,id,"principal_type",type,"user_id",type.equals("USER")?user:null,"group_id",type.equals("GROUP")?group:null));}}
 @SuppressWarnings("unchecked") public static List<Map<String,Object>> readers(Map<String,Object> body){Object v=body.get("readers");if(!(v instanceof List<?> list)||list.size()>1000||list.stream().anyMatch(x->!(x instanceof Map)))throw invalid("readers 必须是授权列表");return (List<Map<String,Object>>)v;}
 public static String required(Map<String,Object> b,String key,int max){String s=Json.str(b,key).strip();if(s.isEmpty()||s.length()>max)throw invalid(key+" 无效");return s;}
 public static long number(Map<String,Object>b,String key){try{return Long.parseLong(required(b,key,20));}catch(NumberFormatException e){throw invalid(key+" 无效");}}
 public static ApiException invalid(String m){return new ApiException(400,"INVALID_INPUT",m);}
 public static ApiException conflict(){return new ApiException(409,"VERSION_CONFLICT","数据已变化，请刷新后重试");}
}
